// EduPath Planner Output Validator

const raw = $json.text;

if (!raw || typeof raw !== 'string') {
  throw new Error('Planner returned no text output.');
}

// Remove accidental Markdown JSON fences if the model adds them
const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let plan;

try {
  plan = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `Planner returned invalid JSON: ${error.message}`
  );
}

// Top-level validation
if (!plan.plan_title || typeof plan.plan_title !== 'string') {
  throw new Error('Missing or invalid plan_title.');
}

if (!plan.reason || typeof plan.reason !== 'string') {
  throw new Error('Missing or invalid reason.');
}

if (!Array.isArray(plan.steps)) {
  throw new Error('steps must be an array.');
}

if (plan.steps.length < 1 || plan.steps.length > 3) {
  throw new Error('Planner must return between 1 and 3 learning steps.');
}

// Get learner commitment from the previous context node
const learnerProfile =
  $('Edit Fields').item.json.learnerProfile;

const weeklyHours =
  Number(learnerProfile?.weeklyCommitmentHours);

if (!Number.isFinite(weeklyHours) || weeklyHours <= 0) {
  throw new Error('Invalid weekly commitment in learner profile.');
}

const maxMinutes = weeklyHours * 60;

let totalMinutes = 0;

const validPriorities = ['high', 'medium', 'low'];

for (let i = 0; i < plan.steps.length; i++) {
  const step = plan.steps[i];

  const requiredFields = [
    'skill',
    'topic',
    'duration_minutes',
    'practice',
    'evidence',
    'priority'
  ];

  for (const field of requiredFields) {
    if (
      step[field] === undefined ||
      step[field] === null ||
      step[field] === ''
    ) {
      throw new Error(
        `Step ${i + 1} is missing required field: ${field}`
      );
    }
  }

  const duration = Number(step.duration_minutes);

  if (!Number.isInteger(duration) || duration <= 0) {
    throw new Error(
      `Step ${i + 1} has invalid duration_minutes.`
    );
  }

  if (!validPriorities.includes(step.priority)) {
    throw new Error(
      `Step ${i + 1} has invalid priority: ${step.priority}`
    );
  }

  totalMinutes += duration;
}

// Time constraint
if (totalMinutes > maxMinutes) {
  throw new Error(
    `Planner generated ${totalMinutes} minutes, ` +
    `but learner has only ${maxMinutes} minutes available this week.`
  );
}

// Return validated structured data
return {
  json: {
    valid: true,
    plan: plan,
    validation: {
      totalSteps: plan.steps.length,
      totalMinutes: totalMinutes,
      weeklyCommitmentHours: weeklyHours,
      withinWeeklyCommitment: true
    }
  }
};
